import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{r as a,o as c,c as _,a as e,b as t,e as o,d as i,f as s}from"./app-2034fe22.js";const h="/assets/v2-be1db7023a8c01a53a0b0d90de61b926_720w-19bb0c39.jpg",l="/assets/v2-77fe7190585c681d5caf8025be8e7345_720w-a74cbb04.jpg",p={},g={href:"https://www.zhihu.com/question/423745276/answer/1504282950?utm_campaign=&utm_medium=social&utm_oi=943763902366986240&utm_psn=1549079814140841984&utm_source=cn.ticktick.task",target:"_blank",rel:"noopener noreferrer"},u=e("p",null,"用来用去，背单词还是喜欢“墨墨背单词”，网页与PDF翻译还是喜欢“沙拉查词”。",-1),d=e("p",null,"积累方面，就按上面文章试一段时间吧。",-1),m=e("h1",{id:"附录-如何做英语积累本原文",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#附录-如何做英语积累本原文","aria-hidden":"true"},"#"),t(" 附录-如何做英语积累本原文")],-1),w=e("p",null,"有这个想法就很好，因为它对于我们二语习得者或外语学习者来说是科学且高效的。我建议你用电脑或者纸质笔记本分类记录，没错，关键是分类。",-1),b=e("p",null,"**那么怎么分类呢？**可以将学到的表达（句型或词组，但不包括单词）分成“读写类”和“听说类”。",-1),f={href:"https://www.zhihu.com/search?q=%E8%89%BE%E5%AE%BE%E6%B5%A9%E6%96%AF%E9%81%97%E5%BF%98%E6%9B%B2%E7%BA%BF&search_source=Entity&hybrid_search_source=Entity&hybrid_search_extra=%7B%22sourceType%22%3A%22answer%22%2C%22sourceId%22%3A1504282950%7D",target:"_blank",rel:"noopener noreferrer"},E=s('<p>高中生或者大学生国内和出国用到的90%以上的词汇不外乎在四六级词汇（6000词）和雅思词汇（8000词）之内。我们完全可以将其中的生词（听口/读写非积极词汇）过一遍，这样效率更好。</p><p>现在大方向有了。<strong>那么，该记录些什么？怎么去做记录？如何去复习呢？</strong></p><p><strong>1. 听说词汇：</strong></p><p>大概逻辑follow的是“<strong>。。。怎么说</strong>”，这样可以最高效地帮助自己学会最地道的口语表达，<strong>可以有例句，但对于那些名词类的用法或者比较容易掌握的用法，也可以只有词组</strong>：比如 power cut 停电。我看到这个词，不需要例句也知道怎么用。</p><p><strong>我有2个途径去整理：第一，在听力材料中听到，然后记下来；第二，思考这样的表达怎么说，然后自己想一个版本，再去考证，看看有没有更加地道的版本。</strong></p><p>比如“想要<strong>有一定的个人空间</strong>”，我之前曾说：<strong>to have one&#39;s personal space</strong>，这样说没有问题。但是，我后来发现有老外这么说：<strong>to retain a sense of freedom</strong>，我就记了下来。不是说之前的版本不好，而是这样能丰富表达的多样性。我在专栏里的写作也基本上是源于自己平时的整理。</p><p><img src="'+h+'" alt="img" loading="lazy"><br> 我的听说记录本</p><p><strong>2. 读写词汇：</strong></p><p>书面语的东西跟口语化的内容不一样，比较严谨正式。</p>',9),y=e("strong",null,"每项用法最好表明例句和出处",-1),B={href:"https://www.zhihu.com/search?q=achieve&search_source=Entity&hybrid_search_source=Entity&hybrid_search_extra=%7B%22sourceType%22%3A%22answer%22%2C%22sourceId%22%3A1504282950%7D",target:"_blank",rel:"noopener noreferrer"},k={href:"https://www.zhihu.com/search?q=collide+with+sb+over+sth&search_source=Entity&hybrid_search_source=Entity&hybrid_search_extra=%7B%22sourceType%22%3A%22answer%22%2C%22sourceId%22%3A1504282950%7D",target:"_blank",rel:"noopener noreferrer"},v=s('<figure><img src="'+l+'" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>​ 我的读写记录本</p><p>最后，关于<strong>复习方法</strong>，建议遵循艾宾浩斯遗忘曲线，隔一段时间再看一遍，大概7-8遍就可以基本掌握。<strong>另外，在写作和口语（输出）中也要试着去使用，才能从根本上掌握新的用法和表达。</strong></p><p>我自己是这样记录的，这帮助我从<strong>高三英语成绩不及格</strong>，提升到<strong>大二专四及格</strong>，再到<strong>大四专八良好</strong>，再到<strong>研究生成功考入广外同传班</strong>，对我有很大帮助。<strong>鉴于我当时基础也很薄弱，这套方法应该适用于80%以上的同学。</strong></p>',4),x=e("br",null,null,-1),A={href:"https://www.zhihu.com/question/423745276/answer/1504282950",target:"_blank",rel:"noopener noreferrer"},z=e("br",null,null,-1),q=e("br",null,null,-1);function C(I,N){const r=a("ExternalLinkIcon");return c(),_("div",null,[e("p",null,[t("想了想如何才能提高自己的英语水平呢？平时会遇到很多比较地道的用法，好像用哪个软件积累都不尽人意。直到今天，看到这篇文章"),e("a",g,[t("如何做英语积累本"),o(r)]),t("。")]),u,i(" more "),d,m,w,b,e("p",null,[t("**为什么不用将单词记本子里？**这是因为很多单词书或者app已经帮你做了这样的工作，并且这些资源还有辅助记忆（一般是"),e("a",f,[t("艾宾浩斯遗忘曲线"),o(r)]),t("的逻辑）的功能，何必浪费精力去做这些呢？")]),E,e("p",null,[t("因此，"),y,t("（文体不同，非正式，正式或者特别正式以至于庄重的文体用词完全不同；一般来说，越正式的问题名词化现象越严重，比如 "),e("a",B,[t("achieve"),o(r)]),t("变成 make achievement）。比如，我有天看外刊时，发现 "),e("a",k,[t("collide with sb over sth"),o(r)]),t("可以表示意见相左，就记录了下来。例句顺便复制过来，方便以后举一反三。")]),v,e("p",null,[t("作者：考研英语皮特儿"),x,t(" 链接："),e("a",A,[t("https://www.zhihu.com/question/423745276/answer/1504282950"),o(r)]),z,t(" 来源：知乎"),q,t(" 著作权归作者所有。商业转载请联系作者获得授权，非商业转载请注明出处。")])])}const F=n(p,[["render",C],["__file","【英文】如何积累.html.vue"]]);export{F as default};
